boost::asio::thread_pool db_pool{8};           // one pool per dependency
std::counting_semaphore<64> db_admission{64};  // bound the pool's queue

if (!db_admission.try_acquire()) return respond_busy();
boost::asio::post(db_pool, [&, req] {
    auto rows = db.query(req.sql);             // blocking call, isolated pool
    db_admission.release();
    deliver(rows);
});

